import json

LOW=(2,2,2,0,0); UP=(4,4,4,4,4); DEGS=range(6,21); HS=range(1,5)
def wt(x): return sum(x)
def parts(lo,hi,d):
 out=[]
 def rec(a,prev):
  k=len(a)
  if k==5:
   if sum(a)==d: out.append(tuple(a))
   return
  rem=d-sum(a)
  for z in range(min(prev,hi[k],rem),lo[k]-1,-1): rec(a+[z],z)
 rec([],hi[0]); return out
def horiz(lam,mu):
 # mu/lam horizontal iff interlacing mu_1>=lam_1>=mu_2>=...>=lam_5
 return all(mu[i]>=lam[i] and (i==4 or lam[i]>=mu[i+1]) for i in range(5))
def matmul(A,B):
 return [[sum(A[i][k]*B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]
def eye(n): return [[int(i==j) for j in range(n)] for i in range(n)]
def swr(A,i,j): A[i],A[j]=A[j],A[i]
def swc(A,i,j):
 for r in A: r[i],r[j]=r[j],r[i]
def rowadd(A,t,s,q):
 for j in range(len(A[0])): A[t][j]+=q*A[s][j]
def coladd(A,t,s,q):
 for i in range(len(A)): A[i][t]+=q*A[i][s]
def smith_witness(M):
 m=len(M); n=len(M[0]) if m else 0
 A=[r[:] for r in M]; U=eye(m); V=eye(n); k=0
 while k<m and k<n:
  pos=next(((i,j) for i in range(k,m) for j in range(k,n) if A[i][j]),None)
  if pos is None: break
  i,j=pos; swr(A,k,i); swr(U,k,i); swc(A,k,j); swc(V,k,j)
  while True:
   changed=True
   while changed:
    changed=False
    for i in range(k+1,m):
     if A[i][k]:
      q=A[i][k]//A[k][k]; rowadd(A,i,k,-q); rowadd(U,i,k,-q)
      if abs(A[i][k])<abs(A[k][k]) and A[i][k]: swr(A,i,k); swr(U,i,k)
      changed=True; break
    if changed: continue
    for j in range(k+1,n):
     if A[k][j]:
      q=A[k][j]//A[k][k]; coladd(A,j,k,-q); coladd(V,j,k,-q)
      if abs(A[k][j])<abs(A[k][k]) and A[k][j]: swc(A,j,k); swc(V,j,k)
      changed=True; break
   bad=next(((i,j) for i in range(k+1,m) for j in range(k+1,n) if A[i][j]%A[k][k]),None)
   if bad is None: break
   # insert A[i,j] into pivot column, then Euclidean reduction resumes
   i,j=bad; coladd(A,k,j,1); coladd(V,k,j,1)
  if A[k][k]<0:
   rowadd(A,k,k,-2); rowadd(U,k,k,-2)
  k+=1
 return U,A,V
def det_bareiss(A):
 n=len(A)
 if n==0:return 1
 B=[r[:] for r in A]; sign=1; p=1
 for k in range(n-1):
  if B[k][k]==0:
   z=next((i for i in range(k+1,n) if B[i][k]),None)
   if z is None:return 0
   B[k],B[z]=B[z],B[k];sign=-sign
  x=B[k][k]
  for i in range(k+1,n):
   for j in range(k+1,n): B[i][j]=(B[i][j]*x-B[i][k]*B[k][j])//p
  p=x
  for i in range(k+1,n): B[i][k]=0
 return sign*B[-1][-1]
R=[]
for d in DEGS:
 C=parts(LOW,UP,d); rows=[]; labels=[]
 for h in HS:
  for la in parts(LOW,UP,d-h):
   row=[int(horiz(la,mu) and wt(mu)-wt(la)==h) for mu in C]
   rows.append(row); labels.append([h,list(la)])
 M=rows
 U,D,V=smith_witness(M)
 assert matmul(matmul(U,M),V)==D
 assert all(D[i][j]==0 for i in range(len(D)) for j in range(len(C)) if i!=j)
 rank=sum(1 for i in range(min(len(D),len(C))) if D[i][i])
 assert all(D[i][i]==1 for i in range(rank))
 assert abs(det_bareiss(U))==1
 assert abs(det_bareiss(V))==1
 R.append({'degree':d,'columns':[list(x) for x in C],'rowLabels':labels,'M':M,'U':U,'V':V,'D':D,'detU':det_bareiss(U),'detV':det_bareiss(V),'rank':rank})
print(json.dumps({'lower':list(LOW),'upper':list(UP),'hDegrees':list(HS),'witnesses':R},separators=(',',':')))
